  se_permite_mascotas text,
  camping_permitido text,
  codigo_local text,
  relevancia_cultural text
);

create temporary table destination_visit_info_matches on commit drop as
select destination.id as destination_id, payload.*
from destination_visit_info_payload payload
join public.destinations destination
  on destination.status = 'Activo'
 and destination.name = payload.name
 and abs(destination.latitude - payload.latitude) < 0.0000001
 and abs(destination.longitude - payload.longitude) < 0.0000001;

do $$
begin
  if (select count(*) from destination_visit_info_payload) <> 386 then
    raise exception 'Expected 386 visit-information records';
  end if;
  if (select count(*) from destination_visit_info_matches) <> 386 then
    raise exception 'Visit information matched % destinations; expected 386',
      (select count(*) from destination_visit_info_matches);
  end if;
  if (select count(distinct destination_id) from destination_visit_info_matches) <> 386 then
    raise exception 'Visit information did not match destinations one-to-one';
  end if;
end
$$;

insert into public.destination_visit_info (
  destination_id,
  tipo_acceso,
  estado_camino,
  duracion_estimada,
  mejor_temporada,
  recomendaciones_seguridad,
  enlace_web,
  reserva_requerida,
  horario_atencion,
  estacionamiento,
  servicios_sanitarios,
  restaurante_o_soda,
  acceso_para_discapacitados,
  se_permite_mascotas,
  camping_permitido,
  codigo_local,
  relevancia_cultural
)
select
  destination_id,
  tipo_acceso,
  estado_camino,
  duracion_estimada,
  mejor_temporada,
  recomendaciones_seguridad,
  enlace_web,
  reserva_requerida,
  horario_atencion,
  estacionamiento,
  servicios_sanitarios,
  restaurante_o_soda,
  acceso_para_discapacitados,
  se_permite_mascotas,
  camping_permitido,
  codigo_local,
  relevancia_cultural
from destination_visit_info_matches;
